from pathlib import Path
p=Path(__file__).parent/'public'
nav=[('index.html','🏠','Inicio'),('mapa.html','🗺️','Mapa de calor'),('reportes.html','🚮','Reportes'),('recompensas.html','🏆','EcoPuntos'),('admin.html','🛠️','Administración')]
header='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#075c46"><title>{title} | EcoRuta Vinocanchón</title><link rel="stylesheet" href="estilos.css"></head><body data-page="{page}">'''
sidebar='''<div class="layout"><aside class="sidebar" id="sidebar"><a class="brand" href="index.html"><span class="brand-icon">🌿</span><span><strong>EcoRuta</strong><small>VINOCANCHÓN</small></span></a><div class="nav-label">TU MERCADO · TU COMUNIDAD</div><nav>{links}</nav><div class="side-note">💚 <strong>Tu reporte cuenta</strong><p>Una comunidad más limpia empieza contigo.</p></div></aside><div class="workspace"><header class="topbar"><button class="hamburger" id="menuBtn" aria-label="Abrir menú">☰</button><div><small>📍 Cusco, Perú · Plataforma comunitaria</small><h2>{title}</h2></div><div class="account"><span id="userName">Visitante</span><span id="pointBadge" class="pill">⭐ 0</span><button class="ghost small" id="logoutBtn">Salir</button></div></header><main>'''
footer='''</main><footer>🌱 EcoRuta Vinocanchón · Plataforma comunitaria de demostración · Datos compartidos por el servidor</footer></div></div><div id="toast" role="status" class="toast"></div><script src="codigo.js" defer></script></body></html>'''
def page(file,title,content,auth=False):
    if auth: body=header.format(title=title,page='login')+content+'<div id="toast" role="status" class="toast"></div><script src="codigo.js" defer></script></body></html>'
    else:
        links=''.join(f'<a href="{f}" class="nav-link {"selected" if f==file else ""}">{ico} <span>{label}</span></a>' for f,ico,label in nav)
        body=header.format(title=title,page=file.removesuffix('.html'))+sidebar.format(links=links,title=title)+content+footer
    (p/file).write_text(body,encoding='utf-8')
